(7610650, 1231240, 16216, '<td valign="top">Why Too Busy for my Liking, my eye can not determine what to look at, the Title says Exterminator.. So I guess the hanging poster.  Good Luck in Future</td>', 'Why Too Busy for my Liking, my eye can not determine what to look at, the Title says Exterminator.. So I guess the hanging poster.  Good Luck in Future', '2019-01-27 08:47:47.000000', NULL, 1),
(7610651, 1231070, 16216, '<td valign="top">Refreshing after seeing several pictures of over used filters I get a Crisp in focus picture with great use of a Shallow DOF. Nice Job.. The Bird had my eye wanting to see what he/she sees to the right of the frame</td>', 'Refreshing after seeing several pictures of over used filters I get a Crisp in focus picture with great use of a Shallow DOF. Nice Job.. The Bird had my eye wanting to see what he/she sees to the right of the frame', '2019-01-27 08:49:59.000000', NULL, 1),
